  <div class="controls">
    <div class="seg" role="group" aria-label="Kártyák szűrése">
      <button type="button" data-cat="all" aria-pressed="true">Mind</button>
      <button type="button" data-cat="animals" aria-pressed="false">Állatok</button>
      <button type="button" data-cat="colors" aria-pressed="false">Színek</button>
      <button type="button" data-cat="school" aria-pressed="false">Iskola</button>
