<script>
(function () {
  "use strict";

  var CARDS = [
    { id:"a1", en:"dog", hu:"kutya", emoji:"🐶", cat:"animals" },
    { id:"a2", en:"cat", hu:"macska", emoji:"🐱", cat:"animals" },
    { id:"a3", en:"fish", hu:"hal", emoji:"🐟", cat:"animals" },
