    { id:"s10", en:"backpack", hu:"iskolazsák", emoji:"🎒", cat:"school" }
  ];
  var CATS = { animals:"Állatok", colors:"Színek", school:"Iskola" };
  var KEY = "szoforditos-v1";

  var state = { known:{}, streak:0, best:0, cat:"all" };
  var order = CARDS.map(function (c) { return c.id; });
  var grid = document.getElementById("grid");
  var statusEl = document.getElementById("status");

  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;" }[c]; }); }
  function shuffleArr(a) { for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function setStatus(t) { statusEl.textContent = t; }
  function setStat(id, v) { document.getElementById(id).textContent = v; }

  function save() {
    if (window.alfy && window.alfy.storage) {
      try { window.alfy.storage.set(KEY, { known:state.known, streak:state.streak, best:state.best, cat:state.cat, order:order }); } catch (e) {}
    }
  }

  function updateStats() {
    var knownCount = 0, k;
    for (k in state.known) { if (state.known[k]) knownCount++; }
    setStat("total", CARDS.length);
    setStat("known", knownCount);
    setStat("streak", state.streak);
    setStat("best", state.best);
  }

  function cardHTML(c) {
    var known = !!state.known[c.id];
    var back = known
      ? '<span class="mark good" aria-hidden="true">✓</span>'
      : '<button type="button" class="btn" data-action="know" data-id="' + c.id + '" aria-label="Tudtam: ' + esc(c.hu) + ' (' + esc(c.en) + ')">Tudtam!</button>';
    return '<div class="face front" aria-hidden="true">'
      + '<span class="tag">' + CATS[c.cat] + '</span>'
      + '<span class="emoji" aria-hidden="true">' + c.emoji + '</span>'
      + '<span class="word">' + esc(c.hu) + '</span></div>'
      + '<div class="face back" aria-hidden="true">' + back + '</div>';
  }

  function render() {
    var ids = order.filter(function (id) { return state.cat === "all" || byId(id).cat === state.cat; });
    if (!ids.length) {
      grid.innerHTML = '<div class="empty"><div class="emoji">📭</div><p>Ebben a kategóriában még nincs kártya. Válassz másikat!</p></div>';
      return;
    }
    grid.innerHTML = ids.map(function (id) {
      var c = byId(id);
      return '<div class="card" tabindex="0" role="button" data-id="' + c.id + '" aria-pressed="false" aria-label="Magyar szó: ' + esc(c.hu) + '. Kattints a fordításért.">' + cardHTML(c) + '</div>';
    }).join("");
  }

  function byId(id) { for (var i = 0; i < CARDS.length; i++) { if (CARDS[i].id === id) return CARDS[i]; } return null; }

  function flipCard(el) {
    el.classList.add("flipped");
    el.setAttribute("aria-pressed", "true");
    el.setAttribute("aria-label", "Angol szó: " + byId(el.dataset.id).en + ". Kattints a magyar szóért.");
    setStatus("Fordítás: " + byId(el.dataset.id).en);
  }

  function markKnown(id) {
    state.known[id] = true;
    state.streak++;
    if (state.streak > state.best) state.best = state.streak;
    save();
    updateStats();
    setStatus("Szép munka! 🎉 Sorozatod: " + state.streak);
    var el = grid.querySelector('.card[data-id="' + id + '"]');
    if (el) {
      var back = el.querySelector(".back");
      if (back) {
        back.innerHTML = '<span class="mark good" aria-hidden="true">✓</span>';
        var fr = byId(id);
        el.setAttribute("aria-label", "Ezt már tudod: " + esc(fr.hu) + " = " + esc(fr.en));
      }
    }
  }

  grid.addEventListener("click", function (e) {
    var btn = e.target.closest("[data-action='know']");
    if (btn) { markKnown(btn.dataset.id); return; }
    var card = e.target.closest(".card");
    if (card && !card.classList.contains("flipped")) flipCard(card);
  });
  grid.addEventListener("keydown", function (e) {
    if (e.key !== "Enter" && e.key !== " ") return;
    var card = e.target.closest(".card");
    if (card && !e.target.closest("[data-action='know']") && !card.classList.contains("flipped")) {
      e.preventDefault(); flipCard(card);
