      save(); render(); setStatus("");
    });
  });
  document.getElementById("shuffle").addEventListener("click", function () {
    shuffleArr(order); save(); render(); setStatus("Kártyák megkeverve 🔀");
  });
  document.getElementById("reset").addEventListener("click", function () {
    state.known = {}; state.streak = 0; state.best = 0;
    save(); render(); updateStats(); setStatus("Újrakezdés! Sok sikert! 🍀");
  });

  (function init() {
    if (window.alfy && window.alfy.storage) {
      window.alfy.storage.get(KEY).then(function (saved) {
        if (saved && typeof saved === "object") {
          if (saved.known) state.known = saved.known;
          if (typeof saved.streak === "number") state.streak = saved.streak;
          if (typeof saved.best === "number") state.best = saved.best;
          if (saved.cat) state.cat = saved.cat;
          if (Array.isArray(saved.order) && saved.order.length === CARDS.length) order = saved.order;
        }
        finishInit();
      }).catch(finishInit);
    } else { finishInit(); }
  })();

  function finishInit() {
    document.querySelectorAll(".seg button").forEach(function (x) { x.setAttribute("aria-pressed", String(x.dataset.cat === state.cat)); });
    updateStats();
    render();
  }
})();
</script>
